window.docContents[223].resolve({"/releases/#subproject-call":{"contents":"These invocations rely on some of Lake's environment variables being overridden, because otherwise the Lake and Lean subprocesses in the build may inherit settings that do not properly apply to them.\nAll these invocations now rely on a standard set of helpers that consistently invoke them correctly.\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes\u0009Verso 4.36.0","header":"Standardized Elan Invocation","id":"/releases/#subproject-call"}});